# T1: abstract Sylvester line image P=[-L,L]^3 cap {sum even}; is J(P) generated by width powers + 2-dim integer projections?
import sys, itertools, math
from rlib import *
L=int(sys.argv[1]); Dmax=int(sys.argv[2]); K=int(sys.argv[3])
P3=[p for p in itertools.product(range(-L,L+1),repeat=3) if sum(p)%2==0]
print("|P|",len(P3))
ys=sp.symbols('a b c')
JP=J_exact(P3,Dmax)
print("dim J(P)_D", [len(JP[D]) for D in range(Dmax+1)])
def prim(v):
    g=0
    for x in v: g=math.gcd(g,abs(x))
    return g==1
dirs=[v for v in itertools.product(range(-K,K+1),repeat=3) if prim(v) and next(x for x in v if x)>0]
# width powers
W=[]
for v in dirs:
    vals={sum(a*b for a,b in zip(v,p)) for p in P3}
    if len(vals)<=Dmax: W.append(sp.Poly(sp.expand(sum(a*y for a,y in zip(v,ys))**len(vals)),*ys))
print("width powers (deg<=Dmax):",len(W))
for D in range(Dmax+1):
    print(" D",D,"width",ideal_dim(W,ys,D)[0])
# 2-dim projections: kernel direction n, basis of n^perp lattice
G=list(W)
seen=set()
for n in dirs:
    # integer basis of n^perp: use sympy nullspace and lll-ish; any rational basis fine
    M=sp.Matrix([list(n)])
    ns=M.nullspace()
    B=[]
    for v in ns:
        den=1
        for x in v: den=sp.ilcm(den,sp.fraction(x)[1])
        B.append([int(x*den) for x in v])
    img=sorted({tuple(sum(a*b for a,b in zip(u,p)) for u in B) for p in P3})
    Jimg=J_exact(img,Dmax)
    for D in range(Dmax+1):
        if Jimg[D]:
            G+=pull_forms(Jimg[D], monos(2,D), B, ys)
for D in range(Dmax+1):
    print(" D",D,"width+2dim-proj",ideal_dim(G,ys,D)[0], "J(P)",len(JP[D]))
